"""Environment for the MemBlock-level `DCacheWrapper` DUT.

`DCacheWrapper` is a *structural* wrapper around the very same `DCache` RTL used
by the DCache top-level UT: it instantiates one `DCache` and renames two port
groups (866 identity connections + 14 cache-control + 39 speculative-fabric
renames).  There is no additional datapath, no uncache arbitration and no third
L2 channel inside this module — the real `Uncache` sits next to it in
`MemBlock.sv`.

Therefore the honest way to verify the wrapper is:

1. prove the port mapping is complete and 1:1 (from the generated RTL, not by
   assumption), and
2. run the same behavioural checks through the *wrapper* ports, so that the
   rename layer plus the wrapped DCache really produces the expected results.

`WrapperDutView` provides exactly that: an attribute view that maps the wrapper
port names onto the DCache port names used by `DcacheEnv`.  The DUT under test is
the real `DCacheWrapper` netlist; only the Python attribute names are translated.
"""
from __future__ import annotations
from suites.memblock.dcache import ROOT as _SUITE_ROOT

import json
from dataclasses import dataclass
from pathlib import Path

from suites.memblock.dcache.testbenches.dcache.env import DcacheEnv

ROOT = _SUITE_ROOT
PERF_OUTPUTS = 42  # DCacheWrapper manifest perf_output_count


@dataclass(frozen=True)
class FabricState:
    """Immutable wrapper speculative-fabric port state."""

    candidate_valid: tuple[int, ...]
    resolve_valid: tuple[int, ...]
    committed: tuple[int, ...]


@dataclass(frozen=True)
class FabricCandidate:
    """One speculative-miss candidate observed at the wrapper boundary."""

    index: int
    paddr: int
    grow: int
    channel: int
    cycle: int


def load_portmap() -> dict:
    path = ROOT / "manifest/dcache-wrapper-portmap.json"
    return json.loads(path.read_text())


class WrapperDutView:
    """Map wrapper port names to the inner DCache port names.

    The mapping comes from `manifest/dcache-wrapper-portmap.json`, generated by
    `tools/wrapper_portmap.py` from the actual `DCacheWrapper.sv` instantiation.
    Anything not listed is an identity connection.
    """

    def __init__(self, dut) -> None:
        self._dut = dut
        portmap = load_portmap()
        # wrapper -> inner, so `getattr(view, <DCache port name>)` resolves the
        # corresponding wrapper pin (identity for 766 ports).
        self._rename = dict(portmap["wrapper_to_inner"])
        self.mapping = portmap

    def __getattr__(self, name: str):
        inner = self._rename.get(name, name)
        return getattr(self._dut, inner)


class DcacheWrapperEnv(DcacheEnv):
    """DCache environment driven through the DCacheWrapper ports."""

    def __init__(self, dut, coverage=None) -> None:
        self.raw_dut = dut
        self.view = WrapperDutView(dut)
        self.ctrl = {
            "a_ready": dut.auto_uncache_in_a_ready,
            "a_valid": dut.auto_uncache_in_a_valid,
            "a_opcode": dut.auto_uncache_in_a_bits_opcode,
            "a_size": dut.auto_uncache_in_a_bits_size,
            "a_source": dut.auto_uncache_in_a_bits_source,
            "a_address": dut.auto_uncache_in_a_bits_address,
            "a_mask": dut.auto_uncache_in_a_bits_mask,
            "a_data": dut.auto_uncache_in_a_bits_data,
            "d_ready": dut.auto_uncache_in_d_ready,
            "d_valid": dut.auto_uncache_in_d_valid,
            "d_opcode": dut.auto_uncache_in_d_bits_opcode,
            "d_size": dut.auto_uncache_in_d_bits_size,
            "d_source": dut.auto_uncache_in_d_bits_source,
            "d_data": dut.auto_uncache_in_d_bits_data,
        }
        super().__init__(self.view, coverage)

    # ------------------------------------------------------- control register
    def ctrl_write(self, index: int, data: int, mask: int = 0xFF, *,
                   source: int = 7) -> dict:
        self.ctrl["a_valid"].Set(1)
        self.ctrl["a_opcode"].Set(0)      # PutFullData
        self.ctrl["a_size"].Set(3)
        self.ctrl["a_source"].Set(source)
        self.ctrl["a_address"].Set(index * 8)
        self.ctrl["a_mask"].Set(mask)
        self.ctrl["a_data"].Set(data)
        self.ctrl["d_ready"].Set(1)
        accepted = False
        for _ in range(8):
            self.refresh()
            if self._val(self.ctrl["a_ready"]):
                accepted = True
                break
            self.dut.Step(1)
        if not accepted:
            self.ctrl["a_valid"].Set(0)
            raise AssertionError(f"ctrl write index {index}: A channel stayed busy")
        self.dut.Step(1)
        self.ctrl["a_valid"].Set(0)
        response = None
        for _ in range(8):
            self.refresh()
            if self._val(self.ctrl["d_valid"]):
                response = {
                    "opcode": self._val(self.ctrl["d_opcode"]),
                    "size": self._val(self.ctrl["d_size"]),
                    "source": self._val(self.ctrl["d_source"]),
                    "data": self._val(self.ctrl["d_data"]),
                }
                self.dut.Step(1)
                return response
            self.dut.Step(1)
        raise AssertionError(f"ctrl write index {index}: no D response")

    def ctrl_read(self, index: int, *, source: int = 7) -> dict:
        self.ctrl["a_valid"].Set(1)
        self.ctrl["a_opcode"].Set(4)      # Get
        self.ctrl["a_size"].Set(3)
        self.ctrl["a_source"].Set(source)
        self.ctrl["a_address"].Set(index * 8)
        self.ctrl["a_mask"].Set(0)
        self.ctrl["a_data"].Set(0)
        self.ctrl["d_ready"].Set(1)
        for _ in range(8):
            self.refresh()
            if self._val(self.ctrl["a_ready"]):
                break
            self.dut.Step(1)
        else:
            self.ctrl["a_valid"].Set(0)
            raise AssertionError(f"ctrl read index {index}: A channel stayed busy")
        self.dut.Step(1)
        self.ctrl["a_valid"].Set(0)
        for _ in range(8):
            self.refresh()
            if self._val(self.ctrl["d_valid"]):
                response = {
                    "opcode": self._val(self.ctrl["d_opcode"]),
                    "size": self._val(self.ctrl["d_size"]),
                    "source": self._val(self.ctrl["d_source"]),
                    "data": self._val(self.ctrl["d_data"]),
                }
                self.dut.Step(1)
                return response
            self.dut.Step(1)
        raise AssertionError(f"ctrl read index {index}: no D response")

    # ------------------------------------------------- wrapper port inventory
    def wrapper_pin_names(self) -> frozenset[str]:
        """The actual generated wrapper pin set, without exposing the handle."""
        return frozenset(self.raw_dut.xport.GetKeys())

    def perf_internal_net(self, index: int) -> str:
        """Inner net that drives one wrapper perf output (manifest check)."""
        if type(index) is not int or not 0 <= index < PERF_OUTPUTS:
            raise ValueError(f"perf index must be 0..{PERF_OUTPUTS - 1}: {index!r}")
        wrapper_pin = f"io_perf_{index}_value"
        connections = self.view.mapping["internal_connections"]
        if wrapper_pin not in connections:
            raise KeyError(f"perf output {index} is not a wrapper internal connection")
        return connections[wrapper_pin]

    def perf_counter_names(self) -> tuple[str, ...]:
        return tuple(self.view.mapping["perf_outputs"])

    def perf_snapshot(self) -> tuple[int, ...]:
        """Immutable snapshot of the 42 wrapper perf outputs."""
        return tuple(int(getattr(self.raw_dut, name).value)
                     for name in self.perf_counter_names())

    # --------------------------------------------------- speculative fabric
    def fabric_state(self) -> FabricState:
        """Sample candidate/resolve/committed vectors through wrapper pins."""
        candidate = tuple(
            int(getattr(self.raw_dut,
                        f"auto_dcache_spec_fabric_source_out_candidate_{index}_valid").value)
            for index in range(3))
        resolve = tuple(
            int(getattr(self.raw_dut,
                        f"auto_dcache_spec_fabric_source_out_resolve_{index}_valid").value)
            for index in range(3))
        committed = tuple(
            int(getattr(self.raw_dut,
                        f"auto_dcache_spec_fabric_source_out_committed_{index}").value)
            for index in range(3))
        return FabricState(candidate, resolve, committed)

    @staticmethod
    def _fabric_vector(values, name: str) -> tuple[bool, ...]:
        """Validate one three-bit fabric vector without truthiness coercion."""
        if type(values) not in (tuple, list) or len(values) != 3:
            raise ValueError(f"{name} must be a three-element tuple/list: {values!r}")
        for value in values:
            if type(value) not in (bool, int) or value not in (0, 1):
                raise ValueError(f"{name} entries must be bool or 0/1: {value!r}")
        return tuple(bool(value) for value in values)

    def drive_fabric_committed(self, values) -> None:
        """Drive the fabric committed inputs from one immutable vector."""
        for index, value in enumerate(
                self._fabric_vector(values, "committed vector")):
            getattr(self.raw_dut,
                    f"auto_dcache_spec_fabric_source_out_committed_{index}").Set(
                        1 if value else 0)

    def drive_fabric_candidate_ready(self, values) -> None:
        for index, value in enumerate(
                self._fabric_vector(values, "candidate-ready vector")):
            getattr(self.raw_dut,
                    f"auto_dcache_spec_fabric_source_out_candidate_{index}_ready").Set(
                        1 if value else 0)

    def _peek_fabric_candidate(self, cycle: int) -> FabricCandidate | None:
        candidate = None
        for index in range(3):
            valid = int(getattr(
                self.raw_dut,
                f"auto_dcache_spec_fabric_source_out_candidate_{index}_valid").value)
            if not valid:
                continue
            candidate = FabricCandidate(
                index=index,
                paddr=int(getattr(
                    self.raw_dut,
                    f"auto_dcache_spec_fabric_source_out_candidate_{index}_bits_paddr").value),
                grow=int(getattr(
                    self.raw_dut,
                    f"auto_dcache_spec_fabric_source_out_candidate_{index}_bits_grow").value),
                channel=int(getattr(
                    self.raw_dut,
                    f"auto_dcache_spec_fabric_source_out_candidate_{index}_bits_channel").value),
                cycle=cycle,
            )
        return candidate

    def watch_fabric_candidate(self, limit: int = 8, stop_lane: int = 0,
                               stop_cycle: int = 1) -> FabricCandidate | None:
        """Wait for a speculative-miss candidate and release the load at S1.

        The load is withdrawn at ``stop_cycle`` *after* that cycle is sampled
        and *before* the next edge, matching the frozen scenario.  A candidate
        seen in the same cycle is returned after the withdrawal, so the input
        is never left asserted after the helper returns.
        """
        if type(limit) is not int or limit < 1:
            raise ValueError(f"fabric limit must be a positive int: {limit!r}")
        if type(stop_lane) is not int or not 0 <= stop_lane < 3:
            raise ValueError(f"stop lane must be 0..2: {stop_lane!r}")
        if type(stop_cycle) is not int or not 0 <= stop_cycle < limit:
            raise ValueError(
                f"stop cycle must be in 0..{limit - 1}: {stop_cycle!r}")
        candidate = None
        for cycle in range(limit):
            self.refresh()
            candidate = self._peek_fabric_candidate(cycle)
            if cycle == stop_cycle:
                self.stop_load(stop_lane)
            if candidate is not None:
                break
            self.dut.Step(1)
        return candidate
